import type { SwfMatrix } from '../assets/asset-pack';
import { MAIN_MENU, type MainMenuMotion } from './main-menu';
import { MENU_SERIES, type SeriesControl } from './menu-series';
import type { Vec } from './types';

export type MenuTarget =
  | { kind: 'control' | 'decoration'; name: string }
  | { kind: 'series'; name?: SeriesControl }
  | { kind: 'blocked' };

export function sameMenuTarget(a?: MenuTarget, b?: MenuTarget) {
  return (
    a?.kind === b?.kind &&
    (a && 'name' in a ? a.name : undefined) === (b && 'name' in b ? b.name : undefined)
  );
}

export function menuLocal(point: Vec, matrix: SwfMatrix): Vec | undefined {
  const det = matrix.a * matrix.d - matrix.b * matrix.c;
  if (Math.abs(det) < 1e-9) return;
  const x = point.x - matrix.tx / 20,
    y = point.y - matrix.ty / 20;
  return { x: (matrix.d * x - matrix.c * y) / det, y: (-matrix.b * x + matrix.a * y) / det };
}

/** Procedural UI input follows its painted ellipses/capsule, including the last link's round end. */
export function mockMenuTarget(point: Vec, motion: MainMenuMotion): MenuTarget | undefined {
  const series = menuLocal(point, MAIN_MENU.series.matrix)!;
  for (const p of [...MENU_SERIES.controls].reverse()) {
    const name = p.name as SeriesControl;
    if (!motion.series.activeControls.includes(name)) continue;
    const local = menuLocal(series, p.matrix)!,
      b = p.bounds;
    if (local.x < b.x || local.x > b.x + b.width || local.y < b.y || local.y > b.y + b.height)
      continue;
    const radius = b.height / 2,
      rightCenter = b.x + b.width - radius;
    if (
      name !== 'bttd_mc' ||
      local.x <= rightCenter ||
      Math.hypot(local.x - rightCenter, local.y - b.y - radius) <= radius
    )
      return { kind: 'series', name };
  }
  const radius = 11,
    width = motion.series.width;
  const nearest = Math.max(radius, Math.min(width - radius, series.x));
  if (Math.hypot(series.x - nearest, series.y - radius) <= radius) return { kind: 'series' };
  for (const p of [...MAIN_MENU.controls].reverse()) {
    const local = menuLocal(point, p.matrix)!,
      b = p.bounds;
    const x = (local.x - b.x - b.width / 2) / (b.width / 2),
      y = (local.y - b.y - b.height / 2) / (b.height / 2);
    if (x * x + y * y <= 1) return { kind: 'control', name: p.name };
  }
}
import { expect, test } from 'bun:test';
import { menuLocal, mockMenuTarget, sameMenuTarget } from '../src/game/core/menu-hit';
import { MAIN_MENU, MainMenuMotion } from '../src/game/core/main-menu';

test('menu picking inverts full twip matrices, including rotated nonuniform scales', () => {
  expect(menuLocal({ x: 7, y: 24 }, { a: 0, b: 2, c: -3, d: 0, tx: 200, ty: 400 })).toEqual({
    x: 2,
    y: 1,
  });
  expect(menuLocal({ x: 0, y: 0 }, { a: 0, b: 0, c: 0, d: 0, tx: 0, ty: 0 })).toBeUndefined();
});

test('pointer targets retain identity across frame probes while distinguishing inert wrappers', () => {
  expect(sameMenuTarget(undefined, undefined)).toBe(true);
  expect(
    sameMenuTarget({ kind: 'control', name: 'play_btn' }, { kind: 'control', name: 'play_btn' }),
  ).toBe(true);
  expect(
    sameMenuTarget({ kind: 'control', name: 'play_btn' }, { kind: 'decoration', name: 'play_btn' }),
  ).toBe(false);
  expect(sameMenuTarget({ kind: 'series' }, { kind: 'series', name: 'bt_mc' })).toBe(false);
});

test('procedural buttons reject empty bounding-box corners but retain their painted ellipse centers', () => {
  const motion = new MainMenuMotion();
  for (const p of MAIN_MENU.controls) {
    const { matrix: m, bounds: b } = p;
    const center = {
      x: m.tx / 20 + (b.x + b.width / 2) * m.a,
      y: m.ty / 20 + (b.y + b.height / 2) * m.d,
    };
    expect(mockMenuTarget(center, motion)).toEqual({ kind: 'control', name: p.name });
    const corner = { x: m.tx / 20 + (b.x + 0.1) * m.a, y: m.ty / 20 + (b.y + 0.1) * m.d };
    expect(mockMenuTarget(corner, motion)).toBeUndefined();
  }
});

test('procedural series uses the capsule and transparent link primitives, including the round final end', () => {
  const motion = new MainMenuMotion();
  expect(mockMenuTarget({ x: 5.1, y: 420.1 }, motion)).toBeUndefined();
  expect(mockMenuTarget({ x: 50, y: 431 }, motion)).toEqual({ kind: 'series' });
  motion.series.hover(true);
  for (let i = 0; i < 8; i++) motion.advance();
  expect(mockMenuTarget({ x: 175, y: 431 }, motion)).toEqual({ kind: 'series', name: 'bt_mc' });
  expect(mockMenuTarget({ x: 405.5, y: 431 }, motion)).toEqual({ kind: 'series', name: 'bttd_mc' });
  expect(mockMenuTarget({ x: 405.5, y: 420.1 }, motion)).toBeUndefined();
});

