def u(n):
    result = []
    while n > 127:
        result.append((n & 127) | 128)
        n >>= 7
    return bytes(result + [n])


def tag(code, data=b''):
    return (struct.pack('<H', (code << 6) | min(len(data), 63))
            + (struct.pack('<I', len(data)) if len(data) >= 63 else b'') + data)


names = ['MenuPointerProbe', 'Main', 'trace', 'name', 'parent', 'target',
